// Map Bluesky feed → analytics_events rows
// AT Protocol feed item: { post: { uri, cid, record, replyCount, repostCount, likeCount, indexedAt } }
// Refs: docs/specs/devrel-analytics-stack.md Decision 4
const feed = $json.feed || [];
const rows = [];

for (const item of feed) {
  const post = item.post;
  if (!post) continue;

  // Extract post ID from AT URI (at://did/app.bsky.feed.post/rkey)
  const uri = post.uri || '';
  const rkey = uri.split('/').pop() || post.cid;
  const contentId = `bluesky:${rkey}`;
  const occurredAt = post.indexedAt || new Date().toISOString();
  const text = post.record?.text || '';

  if (post.likeCount !== undefined) {
    rows.push({
      platform: 'bluesky',
      content_id: contentId,
      event_type: 'like',
      occurred_at: occurredAt,
      metric_value: post.likeCount,
      metadata: JSON.stringify({ uri, text: text.substring(0, 200) })
    });
  }
  if (post.repostCount !== undefined) {
    rows.push({
      platform: 'bluesky',
      content_id: contentId,
      event_type: 'engagement',
      occurred_at: occurredAt,
      metric_value: post.repostCount,
      metadata: JSON.stringify({ uri, metric: 'repost_count' })
    });
  }
  if (post.replyCount !== undefined) {
    rows.push({
      platform: 'bluesky',
      content_id: contentId,
      event_type: 'engagement',
      occurred_at: occurredAt,
      metric_value: post.replyCount,
      metadata: JSON.stringify({ uri, metric: 'reply_count' })
    });
  }
}

return rows.map(row => ({ json: row }));
